import{_ as e,o as a,c as r,a5 as l}from"./chunks/framework.Cooo9kuv.js";const m=JSON.parse('{"title":"XML Sitemap 生成器 — Z-BlogPHP 网站地图插件","description":"","frontmatter":{"标题":"ZBlogPHP 网站地图插件 — XML Sitemap 生成器","日期":"2026-07-11T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["zblog主题插件"],"标签":["SEO优化","Sitemap","URL抓取","XML网站地图","Z-BlogPHP","搜索引擎收录","网站地图生成","自动更新"]},"headers":[{"level":2,"title":"插件简介","slug":"插件简介","link":"#插件简介","children":[]},{"level":2,"title":"功能特性","slug":"功能特性","link":"#功能特性","children":[{"level":3,"title":"三种拆分模式","slug":"三种拆分模式","link":"#三种拆分模式","children":[]},{"level":3,"title":"自动生成机制","slug":"自动生成机制","link":"#自动生成机制","children":[]},{"level":3,"title":"内容类型全覆盖","slug":"内容类型全覆盖","link":"#内容类型全覆盖","children":[]},{"level":3,"title":"自定义更新频率和优先级","slug":"自定义更新频率和优先级","link":"#自定义更新频率和优先级","children":[]},{"level":3,"title":"后台文件管理","slug":"后台文件管理","link":"#后台文件管理","children":[]}]},{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明","children":[{"level":3,"title":"第一步：安装插件","slug":"第一步-安装插件","link":"#第一步-安装插件","children":[]},{"level":3,"title":"第二步：配置参数","slug":"第二步-配置参数","link":"#第二步-配置参数","children":[]},{"level":3,"title":"第三步：生成 Sitemap","slug":"第三步-生成-sitemap","link":"#第三步-生成-sitemap","children":[]},{"level":3,"title":"第四步：提交到搜索引擎","slug":"第四步-提交到搜索引擎","link":"#第四步-提交到搜索引擎","children":[]}]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":2,"title":"反馈与支持","slug":"反馈与支持","link":"#反馈与支持","children":[]},{"level":2,"title":"更新日志","slug":"更新日志","link":"#更新日志","children":[{"level":3,"title":"v1.0.0（2026-07-05）","slug":"v1-0-0-2026-07-05","link":"#v1-0-0-2026-07-05","children":[]}]}],"relativePath":"md/zblog主题插件/ZBlogPHP 网站地图插件 — XML Sitemap 生成器.md","filePath":"md/zblog主题插件/ZBlogPHP 网站地图插件 — XML Sitemap 生成器.md"}'),o={name:"md/zblog主题插件/ZBlogPHP 网站地图插件 — XML Sitemap 生成器.md"};function i(n,t,d,p,s,h){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="xml-sitemap-生成器-—-z-blogphp-网站地图插件" tabindex="-1">XML Sitemap 生成器 — Z-BlogPHP 网站地图插件 <a class="header-anchor" href="#xml-sitemap-生成器-—-z-blogphp-网站地图插件" aria-label="Permalink to &quot;XML Sitemap 生成器 — Z-BlogPHP 网站地图插件&quot;">​</a></h1><blockquote><p>自动生成标准 XML Sitemap 网站地图文件，支持单文件、按类型、按分类三种拆分模式。发布文章自动更新，定时重建保证时效性，帮助搜索引擎高效抓取和收录网站所有页面。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：Z-BlogPHP 1.7.0+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-10.png" alt=""></p><p>本插件用于自动生成符合 sitemaps.org 协议的 XML Sitemap 网站地图文件，将网站首页、分类、标签、文章、页面等链接以标准 XML 格式输出，方便搜索引擎蜘蛛（Google、Bing、百度等）快速发现和抓取网站所有页面。</p><p>插件在后台提供集中化的配置管理界面，支持选择不同的 Sitemap 拆分策略、为每种内容类型单独设置更新频率和优先级、一键手动生成，并可查看已生成文件的列表与详情。同时，插件在前台以访客请求触发的方式实现定时自动重建，无需配置计划任务（Cron），开箱即用。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="三种拆分模式" tabindex="-1">三种拆分模式 <a class="header-anchor" href="#三种拆分模式" aria-label="Permalink to &quot;三种拆分模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>生成文件</th><th>适用场景</th></tr></thead><tbody><tr><td>单文件模式</td><td>所有 URL 合并到一个 <code>sitemap.xml</code></td><td>小型站点，URL 总数较少</td></tr><tr><td>按类型拆分</td><td>首页 / 分类 / 标签 / 文章 / 页面各一个独立 XML 文件 + 索引文件</td><td>中型站点，推荐方案</td></tr><tr><td>按类型拆分</td><td>首页 / 分类 / 标签 / 文章 / 页面各一个独立 XML 文件 + 索引文件</td><td>中型站点，推荐方案</td></tr></tbody></table><p>按类型拆分模式下，插件自动生成一个 Sitemap 索引文件（sitemapindex），汇总指向各子文件的链接，搜索引擎通过索引即可发现所有子地图。按分类拆分模式下，每个分类的文章生成独立文件，方便大型站点分块管理和增量更新。</p><h3 id="自动生成机制" tabindex="-1">自动生成机制 <a class="header-anchor" href="#自动生成机制" aria-label="Permalink to &quot;自动生成机制&quot;">​</a></h3><p>插件提供两种自动生成触发方式：</p><p>— <strong>发布文章自动更新</strong>：当您在后台发布或更新文章、页面时，插件自动重新生成 Sitemap 文件，确保地图内容与网站实际页面实时同步；<br> — <strong>定时自动重建</strong>：通过访客请求触发，按设定的间隔天数自动重建 Sitemap。当前端有访客访问时，插件检查上次生成时间，若超过间隔天数则自动触发一次重建。无需服务器 Cron 支持，间隔灵活可配（0 到 365 天）。</p><p>两种机制可同时启用或单独控制，满足不同更新频率的需求。</p><h3 id="内容类型全覆盖" tabindex="-1">内容类型全覆盖 <a class="header-anchor" href="#内容类型全覆盖" aria-label="Permalink to &quot;内容类型全覆盖&quot;">​</a></h3><p>插件支持 Z-BlogPHP 以下内容类型的 Sitemap 收录，每种类型可独立开关：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>首页</td><td>网站首页链接</td></tr><tr><td>分类</td><td>全部分类页面链接</td></tr><tr><td>标签</td><td>全部标签页面链接</td></tr><tr><td>文章</td><td>所有已发布文章链接</td></tr><tr><td>文章</td><td>所有已发布文章链接</td></tr></tbody></table><p>每种内容类型可单独设置是否包含在 Sitemap 中，未被勾选的类型不会出现在生成的 XML 文件中。</p><h3 id="自定义更新频率和优先级" tabindex="-1">自定义更新频率和优先级 <a class="header-anchor" href="#自定义更新频率和优先级" aria-label="Permalink to &quot;自定义更新频率和优先级&quot;">​</a></h3><p>每种内容类型支持独立设置以下 Sitemap 标准参数：</p><p>— <strong>更新频率（changefreq）</strong>：可选 总是 / 每小时 / 每天 / 每周 / 每月 / 每年 / 从不，告知搜索引擎该类型页面的预期更新频率，帮助蜘蛛合理分配抓取资源；<br> — <strong>优先级（priority）</strong>：0.0 到 1.0 的数值，数值越高表示该类型页面在网站中的重要性越高，搜索引擎会据此调整抓取优先级。</p><p>例如首页可设为「每天 + 1.0」，文章可设为「每月 + 0.6」，精准控制搜索引擎对每种页面的关注度。</p><h3 id="后台文件管理" tabindex="-1">后台文件管理 <a class="header-anchor" href="#后台文件管理" aria-label="Permalink to &quot;后台文件管理&quot;">​</a></h3><p>生成 Sitemap 后，后台页面以表格形式展示所有已生成的文件：</p><p>— 文件名和存在状态（已生成 / 未生成）；<br> — 文件大小（KB），便于了解 Sitemap 体积；<br> — 最后生成时间，确认文件时效性；<br> — 「查看」链接，点击直接在新窗口打开 XML 文件内容预览。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>sitemap_gen</code> 文件夹上传至网站 <code>zb_users/plugin/</code> 目录，进入 Z-BlogPHP 后台「插件管理」页面，找到「XML Sitemap 生成器」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-11.png" alt=""></p><h3 id="第二步-配置参数" tabindex="-1">第二步：配置参数 <a class="header-anchor" href="#第二步-配置参数" aria-label="Permalink to &quot;第二步：配置参数&quot;">​</a></h3><p>进入后台「插件管理 → Sitemap 生成器 → 设置页面」：</p><p>— <strong>文件名</strong>：设置 Sitemap 文件的基础名称，默认为 <code>sitemap</code>，生成的文件为 <code>sitemap.xml</code> 等；<br> — <strong>分类模式</strong>：选择单文件、按类型拆分或按分类拆分三种模式之一，推荐选择「按类型分文件」以获得最佳 SEO 效果；<br> — <strong>发布文章自动生成</strong>：勾选后发布或更新文章/页面时自动重建 Sitemap；<br> — <strong>定时自动生成间隔</strong>：设置定时重建的天数间隔，0 表示关闭定时功能；由访客请求触发，无需服务器 Cron；<br> — <strong>内容类型设置</strong>：针对首页、分类、标签、文章、页面分别设置是否收录、更新频率和优先级。</p><p>配置完成后点击「保存设置」。</p><h3 id="第三步-生成-sitemap" tabindex="-1">第三步：生成 Sitemap <a class="header-anchor" href="#第三步-生成-sitemap" aria-label="Permalink to &quot;第三步：生成 Sitemap&quot;">​</a></h3><p>点击「立即生成 Sitemap」按钮手动生成。生成完成后，页面下方文件列表会显示所有生成的文件及详细信息。点击文件名旁的「查看」链接可直接预览 XML 内容。</p><h3 id="第四步-提交到搜索引擎" tabindex="-1">第四步：提交到搜索引擎 <a class="header-anchor" href="#第四步-提交到搜索引擎" aria-label="Permalink to &quot;第四步：提交到搜索引擎&quot;">​</a></h3><p>Sitemap 文件生成后，可将其 URL 提交到各大搜索引擎的站长平台：</p><p>— Google Search Console：在「站点地图」页面提交 <code>https://你的域名/sitemap.xml</code>；<br> — Bing 网站管理员工具：在「站点地图」页面提交相同的 URL；<br> — 百度搜索资源平台：在「数据引入 → 链接提交 → Sitemap」中提交。</p><p>搜索引擎将定期抓取您提交的 Sitemap 文件，根据其中的 URL 列表发现和收录网站页面。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件生成的是 XML Sitemap 文件（符合 sitemaps.org 协议标准），存储在网站根目录，搜索引擎通过该文件了解网站页面结构，并非直接提升排名；<br> — Sitemap 文件写入网站根目录，请确保 <code>zb_users/plugin/sitemap_gen/</code> 目录（用于缓存状态）和网站根目录（用于写入 XML 文件）具有写入权限；<br> — 定时重建依赖访客请求触发，如果网站在设定间隔时间内没有任何访客访问，定时重建不会执行，可结合手动生成按钮确保文件更新；<br> — 按分类拆分模式下，文章只按分类文件输出，不再生成独立的文章类型文件，避免重复收录；<br> — 如果之前使用其他 Sitemap 插件，建议先卸载旧插件并删除其生成的旧 Sitemap 文件，再启用本插件避免文件冲突。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-05" tabindex="-1">v1.0.0（2026-07-05） <a class="header-anchor" href="#v1-0-0-2026-07-05" aria-label="Permalink to &quot;v1.0.0（2026-07-05）&quot;">​</a></h3><p>— 首次发布，支持标准 XML Sitemap 文件自动生成；<br> — 三种拆分模式：单文件 / 按类型 / 按分类，覆盖不同规模站点；<br> — 发布文章自动更新 Sitemap（基于 PostSucceed 钩子）；<br> — 定时自动重建机制（按间隔天数，由访客请求触发）；<br> — 五种内容类型独立开关，支持自定义更新频率（changefreq）和优先级（priority）；<br> — 后台手动生成按钮 + 文件列表表格查看；<br> — 后台菜单开关和卸载清空数据选项。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2985.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2985.html</a></p>',49)])])}const c=e(o,[["render",i]]);export{m as __pageData,c as default};
